const searchRequest = {
  model: 'groq/compound',
  messages: [
    {
      role: 'system',
      content: 'Search the web only for content from straitstimes.com and return JSON only. Find the best Straits Times matches for the user draft.'
    },
    {
      role: 'user',
      content: $json.search_prompt
    }
  ],
  response_format: {
    type: 'json_object'
  },
  temperature: 0.2,
  max_completion_tokens: 1200
};

return [{
  json: {
    ...$json,
    search_request: searchRequest
  }
}];

const raw = $json.choices?.[0]?.message?.content || '{}';
const cleaned = String(raw).replace(/```json|```/gi, '').trim();
let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  parsed = {
    search_summary: 'Search response could not be parsed.',
    matched_articles: []
  };
}

const upstream = $items('Build Search Request', 0, 0)?.json || {};
const matchedArticles = Array.isArray(parsed.matched_articles)
  ? parsed.matched_articles.slice(0, 5).map((article) => ({
      title: String(article.title || ''),
      url: String(article.url || ''),
      relevance_note: String(article.relevance_note || '')
    }))
  : [];

return [{
  json: {
    ...upstream,
    search_summary: String(parsed.search_summary || ''),
    matched_articles: matchedArticles
  }
}];

const matchesText = ($json.matched_articles || []).length
  ? $json.matched_articles.map((article, index) => {
      return `${index + 1}. ${article.title}\nURL: ${article.url}\nWhy relevant: ${article.relevance_note}`;
    }).join('\n\n')
  : 'No strong Straits Times matches were found.';

const comparePrompt = [
  'You are a verification assistant for SharedSpace.',
  'The draft article is provided below, together with matched Straits Times stories found in step 1.',
  'Judge whether the draft appears reliable enough to publish based on factual alignment, source coverage, bias, logic, and completeness.',
  'Never say the draft is missing unless the draft block below is actually empty.',
  '',
  'Return ONLY valid JSON with this exact shape:',
  '{',
  '  "trust_score": 0,',
  '  "summary": "",',
  '  "verdict": "",',
  '  "metrics": {',
  '    "factual_accuracy": 0,',
  '    "source_quality": 0,',
  '    "bias_detection": 0,',
  '    "logical_consistency": 0,',
  '    "completeness": 0',
  '  },',
  '  "source_label": ""',
  '}',
  '',
  'Scoring rules:',
  '- All scores must be integers from 0 to 100.',
  '- factual_accuracy should reflect how well the draft aligns with matched Straits Times reporting.',
  '- source_quality should be higher when the matched articles strongly support or contextualize the draft.',
  '- bias_detection should be higher when the draft stays balanced and avoids exaggerated framing.',
  '- logical_consistency should be higher when the draft is coherent and does not contradict itself or the matched reporting.',
  '- completeness should be higher when the draft covers the key who/what/when/where/why details supported by the matches.',
  '- If there are no strong matches, make that clear and lower source_quality appropriately rather than pretending the draft is missing.',
  '',
  'Draft article:',
  $json.draft_block || '[missing draft block]',
  '',
  'Search summary:',
  $json.search_summary || '[none]',
  '',
  'Matched Straits Times stories:',
  matchesText
].join('\n');

const compareRequest = {
  model: 'openai/gpt-oss-20b',
  messages: [
    {
      role: 'system',
      content: 'Return JSON only. The draft article is included in the user prompt. Compare it with the matched Straits Times stories and score reliability. Never say the draft is missing unless the prompt literally contains an empty draft block.'
    },
    {
      role: 'user',
      content: comparePrompt
    }
  ],
  response_format: {
    type: 'json_schema',
    json_schema: {
      name: 'sharedspace_st_compare',
      strict: true,
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          trust_score: { type: 'integer' },
          summary: { type: 'string' },
          verdict: { type: 'string' },
          metrics: {
            type: 'object',
            additionalProperties: false,
            properties: {
              factual_accuracy: { type: 'integer' },
              source_quality: { type: 'integer' },
              bias_detection: { type: 'integer' },
              logical_consistency: { type: 'integer' },
              completeness: { type: 'integer' }
            },
            required: ['factual_accuracy', 'source_quality', 'bias_detection', 'logical_consistency', 'completeness']
          },
          source_label: { type: 'string' }
        },
        required: ['trust_score', 'summary', 'verdict', 'metrics', 'source_label']
      }
    }
  },
  temperature: 0.2,
  max_completion_tokens: 900
};

return [{
  json: {
    ...$json,
    compare_prompt: comparePrompt,
    compare_request: compareRequest
  }
}];

const raw = $json.choices?.[0]?.message?.content || '{}';
const cleaned = String(raw).replace(/```json|```/gi, '').trim();
const upstream = $items('Build Compare Request', 0, 0)?.json || {};

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  return [{
    json: {
      trust_score: 0,
      summary: 'AI returned invalid JSON.',
      verdict: 'Verification failed. Check the comparison response in n8n.',
      metrics: {
        factual_accuracy: 0,
        source_quality: 0,
        bias_detection: 0,
        logical_consistency: 0,
        completeness: 0
      },
      source_label: 'Invalid AI response',
      matched_articles: upstream.matched_articles || []
    }
  }];
}

const clamp = (value) => Math.max(0, Math.min(100, parseInt(value ?? 0, 10) || 0));
const metrics = parsed.metrics || {};
const factual = clamp(metrics.factual_accuracy);
const source = clamp(metrics.source_quality);
const bias = clamp(metrics.bias_detection);
const logical = clamp(metrics.logical_consistency);
const completeness = clamp(metrics.completeness);

let trust = clamp(parsed.trust_score);
if (!trust) {
  trust = Math.round((factual + source + bias + logical + completeness) / 5);
}

return [{
  json: {
    trust_score: trust,
    summary: String(parsed.summary || 'Verification completed.'),
    verdict: String(
      parsed.verdict ||
      (trust >= 60
        ? 'Trust score is above 60%. Article can be published.'
        : 'Trust score is below 60%. Revise the article and run verification again.')
    ),
    metrics: {
      factual_accuracy: factual,
      source_quality: source,
      bias_detection: bias,
      logical_consistency: logical,
      completeness
    },
    source_label: String(parsed.source_label || upstream.search_summary || 'Compared against Straits Times matches.'),
    matched_articles: upstream.matched_articles || []
  }
}];
